  dstx_.set_vgpr_msb_role(amdgpu::VgprMsbRole::Dst);
  dsty_.set_vgpr_msb_role(amdgpu::VgprMsbRole::Dst);
  srcx0_.set_vgpr_msb_role(amdgpu::VgprMsbRole::Src0);
  srcy0_.set_vgpr_msb_role(amdgpu::VgprMsbRole::Src0);
